function fenwickBuild(a){ var n=a.length; var bit=new Array(n+1).fill(0); for(var i=1;i<=n;i++){ var idx=i; while(idx<=n){ bit[idx]+=a[i-1]; idx+=idx&-idx; } } return bit; }
function fenwickAdd(bit, i, delta){ var n=bit.length-1; while(i<=n){ bit[i]+=delta; i+=i&-i; } }
function fenwickQuery(bit, i){ var s=0; while(i>0){ s+=bit[i]; i-=i&-i; } return s; }
function fenwickRange(bit, l, r){ return fenwickQuery(bit,r)-fenwickQuery(bit,l-1); }
var EXPORTS={fenwickBuild:fenwickBuild, fenwickAdd:fenwickAdd, fenwickQuery:fenwickQuery, fenwickRange:fenwickRange};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FenwickTreeForgePure = EXPORTS; }
